--
-- Table structure for table `users`
--

DROP TABLE IF EXISTS `users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `users` (
  `id` int NOT NULL AUTO_INCREMENT,
  `openId` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email` varchar(320) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `loginMethod` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `role` enum('user','admin') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'user',
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `lastSignedIn` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `phone` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `birthday` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gender` enum('male','female','other') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `job` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `skills` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `lineId` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `memberNumber` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `memberRole` enum('general','friend','host','premium') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'general',
  `premiumStatus` enum('none','subscribed','expired') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'none',
  `premiumStartDate` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `premiumEndDate` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `subscriptionPlatform` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'restaurant',
  `blackCardMethod` enum('host','friend','subscription','none') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'none',
  `blackCardDate` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `blackCardExpiry` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `blackCardNo` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `blackCardBenefit` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT '全年用餐五折優惠',
